    {
      "objectType": "Concept",
      "evidenceQuote": "第一章介绍了 Agent 的五类工具（感知、执行、协作、事件触发、用户沟通）。为了帮助理解这五类工具的设计差异，可以从两个特征来审视它们：**调用方向**（这次交互由谁发起）和**作用对象**（这次交互作用于什么）。需要说明的是，这两列并不构成一个交叉分类框架——每类工具在“作用对象”上各有专属的取值——它们的作用是帮助读者快速把握每类工具的定位。",
      "canonicalTerm": "Agent 工具分类",
      "aliases": ["工具的分类", "五类工具"],
      "definition": "Agent 工具分为感知、执行、协作、事件触发、用户沟通五类，可从调用方向（交互由谁发起）和作用对象（交互作用于什么）两个特征来理解其定位；这两个特征不构成交叉分类框架，而是帮助把握每类工具的定位。",
      "examples": ["感知工具", "执行工具", "协作工具", "事件触发工具", "用户沟通工具"]
    },
    {
      "objectType": "Concept",
      "evidenceQuote": "**事件触发工具**是外部世界驱动 Agent 行动的方式。例如，设置定时器（set_timer）、监控后台命令行任务（monitor_shell）、连接外部事件源（connect_channel）。这类工具涉及两个时刻：**注册**时由 Agent 主动调用工具，声明自己关心什么事件；**触发**时由外部事件异步回调，唤醒 Agent 开始处理——这正是表4-1 中“Agent 注册、外部触发”的含义。",
      "canonicalTerm": "事件触发工具",
      "aliases": [],
      "definition": "事件触发工具是外部世界驱动 Agent 行动的方式，涉及注册和触发两个时刻：注册时由 Agent 主动调用声明自己关心的事件，触发时由外部事件异步回调唤醒 Agent 开始处理。",
      "examples": ["设置定时器（set_timer）", "监控后台命令行任务（monitor_shell）", "连接外部事件源（connect_channel）"]
    }
  ]
}

{"objects": [
  {
    "objectType": "Concept",
    "evidenceQuote": "今天更成熟的思路被称为 **ACI**（Agent-Computer Interface）：工具应该对应 Agent 的**目标**，而不是底层的 API 操作。ACI 是对标 HCI（人机交互界面）提出的概念——如果说 HCI 研究的是人如何与计算机交互，ACI 研究的就是 Agent 如何与计算机交互，核心是让工具对 Agent 而非对人友好。",
    "canonicalTerm": "ACI",
    "aliases": ["Agent-Computer Interface"],
    "definition": "一种让工具对应 Agent 目标而非底层 API 操作的 Agent-Computer Interface 概念；研究 Agent 如何与计算机交互，核心是让工具对 Agent 而非对人友好。",
    "examples": ["工具对应 Agent 的目标，而不是底层的 API 操作"]
  },
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "工具设计的早期形态是直接的 API 封装——把每个 API 端点包成一个工具，粒度过细，Agent 往往要协调好几个工具才能完成一个目标。今天更成熟的思路被称为 **ACI**（Agent-Computer Interface）：工具应该对应 Agent 的**目标**，而不是底层的 API 操作。ACI 是对标 HCI（人机交互界面）提出的概念——如果说 HCI 研究的是人如何与计算机交互，ACI 研究的就是 Agent 如何与计算机交互，核心是让工具对 Agent 而非对人友好。",
    "statement": "工具应该对应 Agent 的目标，而不是底层的 API 操作。",
    "rationale": "ACI 是对标 HCI 提出的概念，核心是让工具对 Agent 而非对人友好。",
    "appliesWhen": "当工具设计从直接 API 封装转向更成熟的 ACI 思路时。",
    "violation": "把每个 API 端点包成一个工具，粒度过细，Agent 往往要协调好几个工具才能完成一个目标。"
  }
]}

